// === Tab: mySketch ===
// In an involute gear, the profile of each tooth is an involute of a circle. 
// The involute of a circle is the spiraling curve traced by the end of an imaginary 
// taut string unwinding itself from the stationary base circle.
// Contact between a pair of involute gear teeth occurs at a single instantaneous point,
// both increasing the efficiency of the linkage and reducing mechanical wear.
// See: https://en.wikipedia.org/wiki/Involute_gear
// I was inspired to make this after watching the Twitch stream for the 
// Weekly Creative Code Challenge (#WCCChallenge) for the "Drive" prompt. 
// Folks in the chat correctly noted that my bevel gears were not involute!

let turn = 0;
let tspeed = 0;
let alpha = 0;
let beta = 0;
let r = 200;
let next = 0;
let tnum = 0;
let flip = false;
const teeth = 18;
let done = false
let g1x, g2x, tg1x, tg2x, zoom, tzoom;
const sw = 1.5;

function setup() {
	createCanvas(windowWidth, windowHeight);
	gear = createGraphics(width, height);
	drawBase();
	g1x = 0;
	g2x = width;
	tg1x = -1.135 * r;
	tg2x = 2.27 * r;
	zoom = 1;
	tzoom = 1;
	imageMode(CENTER);
}

function drawBase() {
	gear.push();
	gear.translate(width / 2, height / 2);
	gear.stroke(255, 200)
	gear.strokeWeight(1.5);
	gear.noFill();
	gear.ellipse(0, 0, 2 * r, 2 * r);
	gear.ellipse(0, 0, 2.52 * r, 2.52 * r);
	gear.strokeWeight(sw);
	gear.ellipse(0, 0, 20);
	for (let i = 0; i < teeth; i++) {
		let a = i * TAU / teeth - QUARTER_PI / teeth;
		gear.push();
		gear.rotate(a);
		gear.translate(0, -r);
		gear.line(-r / 24, 0, r / 24, 0);
		gear.pop();
	}
	for (let i = 0; i < teeth; i++) {
		var a = i * TAU / teeth + 0.133;
		gear.push();
		gear.rotate(a);
		gear.translate(0, -r * 1.26);
		gear.line(-r / 40, 0, r / 44, 0);
		gear.pop();
	}
	gear.pop();
}

function draw() {
	tzoom = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 1, 3);
	zoom = lerp(zoom, tzoom, 0.1);
	drawTeeth();
	push();
	translate(width / 2, height / 2);
	scale(zoom);
	if (done) {
		turn += tspeed;
		tspeed = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -PI / 360, PI / 360);
		g1x = lerp(g1x, tg1x, 0.1);
		g2x = lerp(g2x, tg2x, 0.1);
		translate(g1x, 0);
		background(0, 32, 130);
		push();
		translate(g2x, 0);
		rotate(-turn);
		rotate(-HALF_PI / teeth);
		image(gear, 0, 0);
		pop();
	}
	rotate(turn);
	image(gear, 0, 0);
	alpha += PI / 120; 
	if (alpha >= 0.75) {
		alpha = 0;
		tnum += 1;
	}
	pop();
	if (done) {
		translate(width / 2, height / 2);
		scale(zoom);
		strokeWeight(sw/2);
		stroke(200, 0, 0, 150);
		push();
		rotate(0.48);
		line(0, r / 2, 0, -r / 2);
		pop();
		push();
		stroke(0, 200, 0, 150);
		rotate(-0.48);
		line(0, -r / 2, 0, r / 2);
		pop();
		stroke(200, 150);
		line(-g1x + r / 8, 0, g1x - r / 8, 0);
		line(-g1x, r / 8, -g1x, -r / 8);
		line(g1x, r / 8, g1x, -r / 8);
	}
}

function drawTeeth() {
	if (tnum >= teeth && !flip) {
		flip = true;
		beta = -1.5 * PI / teeth;
		tnum = 0
	} else if (tnum >= teeth && beta != 0) done = true;
	if (done == false) {
		next = tnum * TAU / teeth;
		background(0, 32, 130);
		stroke(255, 200);
		push();
		translate(width / 2, height / 2);
		scale(zoom);
		if (flip) scale(-1, 1);
		rotate(alpha + beta + next);
		translate(0, -r);
		ellipse(0,0,5)
		let shift = -r * alpha;
		translate(shift, 0);
		translate(0, -10);
		noFill();
		rect(0, 0, QUARTER_PI * r, 10);
		pop();
		gear.push();
		gear.translate(width / 2, height / 2);
		if (flip) gear.scale(-1, 1);
		gear.rotate(alpha + beta + next);
		gear.translate(0, -r);
		gear.translate(shift, 0);
		gear.noStroke();
		gear.fill(255, 200);
		if (alpha != 0) {
			gear.ellipse(0, 0, sw);
			gear.ellipse(0, -sw, sw);
			gear.ellipse(0, -2 * sw, sw);
		}
		gear.pop();
	}
}
